var __line = 1
  , __lines = "<main class=\"tool-page <%= post.kind === 'news' ? 'tool-page--news' : '' %>\">\n  <div class=\"container\">\n    <nav class=\"breadcrumb\" aria-label=\"面包屑\">\n      <a href=\"/\">首页</a>\n      <span>/</span>\n      <a href=\"/category/<%= post.category %>/\"><%= post.categoryName %></a>\n      <span>/</span>\n      <span class=\"current\"><%= post.title.split(' - ')[0] %></span>\n    </nav>\n\n    <header class=\"tool-hero\">\n      <div class=\"tool-cover\">\n        <% if (post.cover && post.cover.url) { %>\n          <img src=\"<%= post.cover.url %>\" alt=\"<%= post.title %>\" loading=\"lazy\">\n        <% } else { %>\n          <span class=\"letter-tile letter-tile--lg\" style=\"background-color: <%= post.cover ? post.cover.color : '#e5484d' %>\"><%= post.cover ? post.cover.letter : 'AI' %></span>\n        <% } %>\n      </div>\n      <div class=\"tool-hero-body\">\n        <h1><%= post.title %></h1>\n        <% if (post.subtitle) { %><p class=\"tool-subtitle\"><%= post.subtitle %></p><% } %>\n        <div class=\"tool-meta\">\n          <a class=\"chip chip--category\" href=\"/category/<%= post.category %>/\"><i data-lucide=\"folder\"></i><%= post.categoryName %></a>\n          <% (post.tags || []).slice(0, 5).forEach(function(t) { %>\n            <a class=\"chip\" href=\"/tag/<%= encodeURIComponent(t) %>/\"><i data-lucide=\"tag\"></i><%= t %></a>\n          <% }) %>\n        </div>\n        <div class=\"tool-actions\">\n          <% if (post.kind === 'news') { %>\n            <% if (post.sourceUrl) { %>\n              <a class=\"btn btn--primary\" href=\"<%= post.sourceUrl %>\" rel=\"nofollow noopener\" target=\"_blank\">\n                <i data-lucide=\"external-link\"></i> 阅读原文\n              </a>\n            <% } %>\n          <% } else if (post.recommendUrl) { %>\n            <a class=\"btn btn--primary\" href=\"<%= post.recommendUrl %>\" rel=\"nofollow noopener sponsored\" target=\"_blank\">\n              <i data-lucide=\"badge-dollar-sign\"></i> 链接直达\n            </a>\n            <% if (post.recommendNote) { %>\n              <span class=\"tool-action-note\"><%= post.recommendNote %></span>\n            <% } %>\n          <% } else if (post.officialUrl) { %>\n            <a class=\"btn btn--primary\" href=\"<%= post.officialUrl %>\" rel=\"nofollow noopener\" target=\"_blank\">\n              <i data-lucide=\"external-link\"></i> 访问官网\n            </a>\n          <% } %>\n          <button class=\"btn btn--ghost copy-link\" data-url=\"<%= canonical %>\">\n            <i data-lucide=\"link\"></i> 复制链接\n          </button>\n        </div>\n      </div>\n      <div class=\"tool-facts\">\n        <div><span><%= post.kind === 'news' ? '发布日期' : '内容类型' %></span><strong><%= post.kind === 'news' ? post.publishedAt.slice(0, 10) : '工具收录' %></strong></div>\n        <div><span>热度指数</span><strong><%= post.hotScore %></strong></div>\n        <div><span>阅读时长</span><strong><%= post.sections.length ? post.sections.map(function(s){return s.body;}).join('').replace(/<[^>]+>/g,'').length : 0 %> 字</strong></div>\n      </div>\n    </header>\n\n    <% if (post.kind === 'tool' && (post.officialUrl || post.recommendUrl)) { %>\n      <section class=\"official-band\" aria-label=\"官网直达\">\n        <div class=\"official-band-title\">\n          <i data-lucide=\"globe\"></i>\n          <span><%= post.recommendUrl ? '链接直达' : '官网直达' %></span>\n        </div>\n        <div class=\"official-links\">\n          <% if (post.recommendUrl) { %>\n            <a href=\"<%= post.recommendUrl %>\" rel=\"nofollow noopener sponsored\" target=\"_blank\">\n              <span class=\"official-link-name\"><%= post.title.split(' - ')[0] %> 链接直达</span>\n              <span class=\"official-link-url\"><%= post.recommendUrl.replace(/^https?:\\/\\//, '').replace(/\\/+$/, '') %></span>\n              <i data-lucide=\"badge-dollar-sign\"></i>\n            </a>\n            <% if (post.recommendNote) { %>\n              <p class=\"official-link-note\"><%= post.recommendNote %></p>\n            <% } %>\n          <% } else if (post.officialUrl) { %>\n            <a href=\"<%= post.officialUrl %>\" rel=\"nofollow noopener\" target=\"_blank\">\n              <span class=\"official-link-name\"><%= post.title.split(' - ')[0] %> 官网</span>\n              <span class=\"official-link-url\"><%= post.officialUrl.replace(/^https?:\\/\\//, '').replace(/\\/+$/, '') %></span>\n              <i data-lucide=\"external-link\"></i>\n            </a>\n          <% } %>\n        </div>\n      </section>\n    <% } %>\n\n    <div class=\"tool-layout\">\n      <article class=\"article\">\n        <% if (toc.length > 2) { %>\n          <nav class=\"toc\" aria-label=\"目录\">\n            <p>目录</p>\n            <ol>\n              <% toc.forEach(function(t) { %>\n                <li><a href=\"#<%= t.id %>\"><%= t.heading %></a></li>\n              <% }) %>\n            </ol>\n          </nav>\n        <% } %>\n\n        <%- include('partials/ad', { slot: 'article-top' }) %>\n\n        <% if (post.kind === 'tool' && post.screenshots && post.screenshots.length) { %>\n          <section class=\"tool-gallery\" id=\"screenshots\">\n            <div class=\"section-block-head\">\n              <h2>产品界面</h2>\n              <p>来自官网与产品公开页的产品图与界面素材</p>\n            </div>\n            <div class=\"tool-shot-grid\">\n              <% post.screenshots.forEach(function(src, i) { %>\n                <a class=\"tool-shot\" href=\"<%= post.recommendUrl || post.officialUrl || post.sourceUrl || '#' %>\" rel=\"nofollow noopener\" target=\"_blank\">\n                  <img src=\"<%= src %>\" alt=\"<%= post.title %> 截图 <%= i + 1 %>\" loading=\"lazy\">\n                </a>\n              <% }) %>\n            </div>\n          </section>\n        <% } %>\n\n        <% (post.sections || []).forEach(function(s, i) { %>\n          <section class=\"section-block\" id=\"<%= 'sec-' + (i + 1) %>\">\n            <h2><%= s.heading %></h2>\n            <div class=\"prose\"><%- s.body %></div>\n            <% if (i === 1) { %><%- include('partials/ad', { slot: 'article-middle' }) %><% } %>\n          </section>\n        <% }) %>\n\n        <% if (post.kind === 'news') { %>\n          <section class=\"section-block\" id=\"source-note\">\n            <h2>来源与说明</h2>\n            <div class=\"prose\">\n              <p>本文由 AI 潮汐编辑部基于官方公告与公开资料整理，补充了行业影响、适用场景和行动建议，帮助你在阅读原文前先理解这条信息为什么重要。</p>\n              <% if (post.sourceUrl) { %>\n                <p>原始来源：<a href=\"<%= post.sourceUrl %>\" rel=\"nofollow noopener\" target=\"_blank\"><%= post.sourceUrl %></a></p>\n              <% } %>\n              <p>如发现事实、价格或链接有误，可通过 <a href=\"/contact/\">联系我们</a> 提交更正。</p>\n            </div>\n          </section>\n        <% } %>\n\n        <% if (post.kind === 'tool' && (post.officialUrl || post.recommendUrl)) { %>\n          <section class=\"section-block\" id=\"official-links\">\n            <h2><%= post.recommendUrl ? '链接直达' : '官网直达' %></h2>\n            <div class=\"prose\">\n              <p><%= post.recommendUrl ? '想亲自上手体验，直接从推荐入口出发：' : '想亲自上手体验，直接从官方入口出发：' %></p>\n              <ul class=\"official-list\">\n                <% if (post.recommendUrl) { %>\n                  <li>\n                    <a href=\"<%= post.recommendUrl %>\" rel=\"nofollow noopener sponsored\" target=\"_blank\">\n                      <span class=\"official-list-name\">链接直达</span>\n                      <span class=\"official-list-url\"><%= post.recommendUrl.replace(/^https?:\\/\\//, '').replace(/\\/+$/, '') %></span>\n                      <i data-lucide=\"badge-dollar-sign\"></i>\n                    </a>\n                    <% if (post.recommendNote) { %>\n                      <p class=\"official-list-note\"><%= post.recommendNote %></p>\n                    <% } %>\n                  </li>\n                <% } else if (post.officialUrl) { %>\n                  <li>\n                    <a href=\"<%= post.officialUrl %>\" rel=\"nofollow noopener\" target=\"_blank\">\n                      <span class=\"official-list-name\"><%= post.title.split(' - ')[0] %> 官网</span>\n                      <span class=\"official-list-url\"><%= post.officialUrl.replace(/^https?:\\/\\//, '').replace(/\\/+$/, '') %></span>\n                      <i data-lucide=\"external-link\"></i>\n                    </a>\n                  </li>\n                <% } %>\n              </ul>\n            </div>\n          </section>\n        <% } %>\n\n        <% if (post.faq && post.faq.length) { %>\n          <section class=\"section-block\" id=\"faq\">\n            <h2>常见问题</h2>\n            <div class=\"faq-list\">\n              <% post.faq.forEach(function(f) { %>\n                <details class=\"faq-item\">\n                  <summary><%= f.q %></summary>\n                  <p><%= f.a %></p>\n                </details>\n              <% }) %>\n            </div>\n          </section>\n        <% } %>\n\n        <div class=\"article-bottom\">\n          <div class=\"prev-next\">\n            <% if (next) { %>\n              <a href=\"/tool/<%= next.slug %>/\">\n                <span>上一篇</span>\n                <strong><%= next.title.split(' - ')[0] %></strong>\n              </a>\n            <% } %>\n            <% if (prev) { %>\n              <a href=\"/tool/<%= prev.slug %>/\">\n                <span>下一篇</span>\n                <strong><%= prev.title.split(' - ')[0] %></strong>\n              </a>\n            <% } %>\n          </div>\n          <div class=\"tag-cloud tag-cloud--bottom\">\n            <% (post.tags || []).forEach(function(t) { %>\n              <a href=\"/tag/<%= encodeURIComponent(t) %>/\"><%= t %></a>\n            <% }) %>\n          </div>\n        </div>\n      </article>\n\n      <aside class=\"sidebar sidebar--article\">\n        <%- include('partials/ad', { slot: 'article-side-top' }) %>\n\n        <section class=\"side-card\">\n          <h2>相关<%= post.kind === 'news' ? '资讯' : '工具' %></h2>\n          <div class=\"related-list\">\n            <% related.forEach(function(p) { %>\n              <a href=\"/tool/<%= p.slug %>/\" class=\"related-item\">\n                <% if (p.cover && p.cover.url) { %>\n                  <img src=\"<%= p.cover.url %>\" alt=\"\">\n                <% } else { %>\n                  <span class=\"letter-tile\" style=\"background-color: <%= p.cover ? p.cover.color : '#e5484d' %>\"><%= p.cover ? p.cover.letter : 'AI' %></span>\n                <% } %>\n                <span><strong><%= p.title.split(' - ')[0] %></strong><em><%= p.categoryName %></em></span>\n              </a>\n            <% }) %>\n            <% if (!related.length) { %><p class=\"muted\">暂无相关内容。</p><% } %>\n          </div>\n        </section>\n\n        <section class=\"side-card\">\n          <h2>最新内容</h2>\n          <ol class=\"rank-list\">\n            <% (latest || []).slice(0, 6).forEach(function(p, i) { %>\n              <li>\n                <span class=\"rank-no\"><%= i + 1 %></span>\n                <a href=\"/tool/<%= p.slug %>/\">\n                  <strong><%= p.title.split(' - ')[0] %></strong>\n                  <span><%= p.kind === 'news' ? p.publishedAt.slice(0, 10) : p.categoryName %></span>\n                </a>\n              </li>\n            <% }) %>\n          </ol>\n        </section>\n\n        <%- include('partials/ad', { slot: 'article-side-bottom' }) %>\n      </aside>\n    </div>\n  </div>\n</main>\n"
